out = [[0]*14 for _ in range(20)]
MR, MC = 7, 0
VAL = 8

# Diamond expansion from marker
for r in range(20):
    for c in range(14):
        dist = abs(r - MR) + abs(c - MC)  # Manhattan distance
        if dist == 0:
            out[r][c] = VAL
        elif dist == 1:
            if c == 0 and r in [MR-1, MR+1]:  # (6,0), (8,0)
                out[r][c] = VAL
            elif c == 1 and r == MR:  # (7,1)
                out[r][c] = VAL
        elif dist == 2:
            if c == 0 and (r in [MR-2, MR+2]):  # (5,0), (9,0)
                out[r][c] = VAL
            elif c == 1 and abs(r - MR) == 1:  # (6,1), (8,1)
                out[r][c] = VAL
            elif c == 2 and r == MR:  # (7,2)
                out[r][c] = VAL

print("Diamond pattern:")
